import configparser

def base_config(user: str, etcd_host: str = "localhost", etcd_port: int = 2379) -> None:
    """
    Creates a configuration with some simple parameters, the key parameters contains "tls", "authentication", "authorization", "etcd", "docs", and "log".
    """
    config = configparser.ConfigParser()
    config['DEFAULT'] = {
        'etcd_host': etcd_host,
        'etcd_port': str(etcd_port)
    }
    config['etcd'] = {
        'tls': 'false',
        'authentication': 'false',
        'authorization': 'false'
    }
    config['docs'] = {
        'url': 'https://example.com/docs'
    }
    config['log'] = {
        'level': 'INFO',
        'format': 'simple'
    }
    with open(f'{user}_config.ini', 'w') as configfile:
        config.write(configfile)

# Example usage:
