def subclasses(cls):
    """
    Return all subclasses of a class, recursively
    """
    import inspect
    subclasses = set()
    visited = set()
    to_visit = [cls]

    while to_visit:
        current_cls = to_visit.pop()
        if current_cls in visited:
            continue
        visited.add(current_cls)
        for name, obj in inspect.getmembers(current_cls):
            if inspect.isclass(obj) and issubclass(obj, cls) and obj not in visited:
                subclasses.add(obj)
                to_visit.append(obj)
    return list(subclasses)

