from typing import List

class Bookmark:
    def __init__(self, title: str, url: str, category: str):
        self.title = title
        self.url = url
        self.category = category

class Bookmarks:
    def __init__(self, bookmarks: List[Bookmark]):
        self.bookmarks = bookmarks

def from_raw_values(values: List[str]) -> Bookmarks:
    """
    Create a Bookmarks object from a list of raw bookmark string values.
    """
    bookmarks = []
    for value in values:
        # Split the value into parts (assuming format: title, url, category)
        parts = value.split(',')
        if len(parts) != 3:
            raise ValueError('Each bookmark must have title, url, and category')
        title, url, category = parts
        # Create a Bookmark object and add it to the list
        bookmark = Bookmark(title, url, category)
        bookmarks.append(bookmark)
    return Bookmarks(bookmarks)
